// /frontend-react/src/components/Dashboard.js (i18n Enabled)

import React from 'react';
import { useTranslation } from 'react-i18next'; // 1. Import useTranslation

// --- DashboardHeader: Simplified Menu Icon ---
// We don't need to change this function, only how we call it in the main component.
const DashboardHeader = ({ onMenuClick, isEasyMode, t }) => ( // Added t prop (optional, but cleaner)
    <div style={{ 
        display: 'flex', 
        justifyContent: 'flex-end', 
        padding: '15px 20px', 
        backgroundColor: 'transparent', 
        position: 'absolute', 
        top: 0,
        right: 0,
        width: '100%',
        zIndex: 15,
    }}>
        <button
            onClick={onMenuClick}
            style={{
                padding: '8px',
                backgroundColor: 'transparent', 
                border: 'none', 
                borderRadius: '0', 
                cursor: 'pointer',
                fontSize: isEasyMode ? '36px' : '28px', 
                color: '#333',
                transition: 'color 0.2s',
            }}
            onMouseOver={e => e.currentTarget.style.color = '#1A73E8'} 
            onMouseOut={e => e.currentTarget.style.color = '#333'}
        >
            {/* 2. Translate ARIA label */}
            <span role="img" aria-label={t('general.menu')}>☰</span>
        </button>
    </div>
);
// --- END DashboardHeader ---


// --- Icon Component Modification ---
const Icon = ({ name, emoji, isActive, onClick, isProminent, isEasyMode, color = '#1A73E8', bgColor = '#E8F0FE' }) => {
    // name is now the translated string, so no change here, but logic relies on name.
    const isColored = isActive || isProminent; 

    // Define specific colors based on the icon's role (The translated name must match the check!)
    let iconColor = color;
    let iconBgColor = bgColor;
    
    // NOTE: This comparison relies on the translated 'name' string matching exactly.
    // A safer, but more complex approach, is to pass a 'key' prop instead of the translated 'name'.
    if (name === "Emergency Info") {
        iconColor = '#DC3545'; // Red for SOS
        iconBgColor = '#FDE9E9';
    } else if (name === "Medical History") {
        iconColor = '#17A2B8'; // Cyan/Teal for History
        iconBgColor = '#E8F7F9';
    }


    return (
        <div 
            onClick={onClick} 
            style={{
                padding: '25px', 
                margin: '15px',
                border: `5px solid ${isColored ? iconColor : '#e0e0e0'}`,
                borderRadius: '15px', 
                width: '40%',
                textAlign: 'center',
                backgroundColor: isColored ? iconBgColor : '#ffffff',
                filter: isColored ? 'none' : 'grayscale(80%)',
                opacity: isColored ? 1 : 0.7, 
                cursor: 'pointer',
                boxShadow: isColored ? `0 8px 15px ${iconColor}4D` : '0 2px 5px rgba(0, 0, 0, 0.1)',
                transition: 'all 0.3s',
                fontSize: isEasyMode ? '32px' : '18px',
            }}
        >
            <span role="img" aria-label={name} style={{fontSize: isEasyMode ? '85px' : '40px', display: 'block', marginBottom: '10px'}}>{emoji}</span>
            {/* The 'name' prop is already the translated text */}
            <p style={{fontWeight: 'bold', color: '#333', margin: 0}}>{name}</p>
        </div>
    );
};
// --- END Icon Component Modification ---


function Dashboard({ isEasyMode, goToMedical, onMenuClick, goToEmergencyInfo }) { 
    // 3. Initialize translation hook
    const { t } = useTranslation();

    const showAppointmentNotification = true; 
    
    // --- REVISED NOTIFICATION STYLE (Floating Card) ---
    const notificationStyle = {
        padding: '15px 25px', 
        margin: '15px', 
        backgroundColor: '#FFF3CD',
        color: '#856404', 
        textAlign: 'center',
        cursor: 'pointer',
        fontSize: isEasyMode ? '24px' : '16px',
        fontWeight: 'bold',
        borderRadius: '10px',
        borderLeft: '5px solid #FFC107', 
        boxShadow: '0 4px 10px rgba(0,0,0,0.1)',
        position: 'relative', 
        zIndex: 10,
    };


    return (
        <div style={{ position: 'relative' }}>
            {/* 4. Pass the t function to DashboardHeader (optional cleanup) */}
            <DashboardHeader onMenuClick={onMenuClick} isEasyMode={isEasyMode} t={t} />

            {/* RENDER THE NOTIFICATION BANNER */}
            {showAppointmentNotification && (
                <div 
                    onClick={goToMedical} 
                    style={notificationStyle}
                >
                    <span role="img" aria-label={t('general.alert')} style={{marginRight: '10px'}}>🔔</span>
                    {/* 5. Translate the full notification phrase */}
                    {t('dashboard.appointment_soon_alert')} {t('general.tap_here')}
                </div>
            )}

            {/* MAIN ICON GRID - FINAL SYMMETRICAL 2X2 ALIGNMENT */}
            <div style={{ 
                display: 'flex', 
                flexWrap: 'wrap', 
                justifyContent: 'center', 
                paddingTop: showAppointmentNotification ? '20px' : '40px', 
                paddingBottom: '40px' 
            }}>
                {/* 6. Translate the icon names */}
                {/* 1. MEDICAL ACCESS (Active Feature) */}
                <Icon 
                    name={t('dashboard.medical_access_card')} 
                    emoji="🏥" 
                    isActive={true} 
                    onClick={goToMedical} 
                    isEasyMode={isEasyMode}
                />
                
                {/* 2. EMERGENCY INFO */}
                <Icon 
                    name={t('dashboard.emergency_info_card')} 
                    emoji="🆘" 
                    isProminent={true} 
                    isActive={false} 
                    onClick={goToEmergencyInfo} 
                    isEasyMode={isEasyMode}
                />
                
                {/* Row 2 */}
                {/* 3. MEDICAL HISTORY */}
                <Icon 
                    name={t('dashboard.medical_history_card')} 
                    emoji="📜" 
                    isProminent={true} 
                    isActive={false} 
                    onClick={() => console.log('Medical History page route needed.')}
                    isEasyMode={isEasyMode}
                />
                
                {/* HIDDEN SPACER ICON: No text, so no translation needed */}
                <div style={{ width: '40%', margin: '15px', visibility: 'hidden' }}></div>
            </div>
        </div>
    );
}

export default Dashboard;
